# 2. File: scripts/hooks/pretool-guard.py (Exit code 2 = chan tat dinh)
# ==========================================================================
import json, re, sys

payload = json.load(sys.stdin)
tool_name = payload.get("tool_name", "")
tool_input = payload.get("tool_input", {})
raw_blob = json.dumps(tool_input, ensure_ascii=False)

# Chan doc/ghi truc tiep tep chua secret ERP/MISA/Meta CAPI va thu muc .git
SENSITIVE_PATH_RE = re.compile(r"(\.env(\..*)?$|id_rsa|\.pem$|\.git/hooks)", re.I)
DANGEROUS_SQL_BASH_RE = re.compile(
    r"(rm\s+-rf\s+/|DROP\s+(TABLE|DATABASE)|TRUNCATE\s+TABLE|curl\s+.*169\.254\.169\.254)", re.I
)

file_path = str(tool_input.get("file_path") or tool_input.get("path") or "")
command = str(tool_input.get("command") or "")

if file_path and SENSITIVE_PATH_RE.search(file_path):
    print(f"[PRETOOLUSE_BLOCKED] Cam truy cap tep nhay cam: {file_path}", file=sys.stderr)
    sys.exit(2)  # Exit code 2 buoc Claude Code chan truoc permission prompt

if tool_name == "Bash" and (DANGEROUS_SQL_BASH_RE.search(command) or ".env" in raw_blob):
    print("[PRETOOLUSE_BLOCKED] Phat hien lenh pha hoai hoac cham tep .env trong Bash.", file=sys.stderr)
    sys.exit(2)

sys.exit(0)

